package com.parvnigam.careerbridge;

import java.net.*;
import java.net.http.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.security.crypto.password.PasswordEncoder;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:passwordtests;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop","app.local-email-testing=true","app.local-inbox-port=0","app.mail-enabled=false","app.redis-enabled=false"})
class PasswordRecoveryTests {
    @LocalServerPort int port;
    @Autowired VerificationMail mail;@Autowired Repositories.Accounts accounts;@Autowired Repositories.Profiles profiles;
    @Autowired PasswordEncoder passwords;@Autowired EmailVerification verification;
    final HttpClient http=HttpClient.newHttpClient();final JsonMapper json=JsonMapper.builder().build();
    static final String OLD="Strong@12345",NEW="Next@54321Strong";
    HttpResponse<String> call(String method,String path,String jwt,Object body)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api"+path));if(jwt!=null)b.header("Authorization","Bearer "+jwt);if(body!=null)b.header("Content-Type","application/json");return http.send(b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
    JsonNode tree(HttpResponse<String> r){return json.readTree(r.body());}
    Model.Account account(){var a=new Model.Account();a.email=UUID.randomUUID()+"@example.com";a.name="Recovery Tester";a.role=Model.Role.STUDENT;a.emailVerified=true;a.emailVerifiedAt=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);a.passwordHash=passwords.encode(OLD);accounts.save(a);var profile=new Model.Profile();profile.userId=a.id;profile.cgpa=8.7;profiles.save(profile);return a;}
    String login(String email,String pw)throws Exception{var r=call("POST","/auth/login",null,Map.of("email",email,"password",pw));assertEquals(200,r.statusCode(),r.body());return tree(r).get("token").asText();}
    HttpResponse<String> request(String email)throws Exception{return call("POST","/auth/forgot-password",null,Map.of("email",email));}
    String awaitToken(Model.Account a,String previous)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(System.nanoTime()<until){String t=null;synchronized(mail.messages){var list=mail.messages.stream().filter(m->m.to().equals(a.email)&&m.kind()==VerificationMail.Kind.PASSWORD_RESET).toList();if(!list.isEmpty())t=list.get(list.size()-1).link().split("#token=")[1];}if(t!=null&&!t.equals(previous)&&EmailVerification.hash(t).equals(accounts.findById(a.id).orElseThrow().passwordResetHash))return t;Thread.sleep(25);}throw new AssertionError("Reset email did not arrive");}
    String issue(Model.Account a)throws Exception{assertEquals(202,request(a.email).statusCode());return awaitToken(a,null);}
    HttpResponse<String> reset(String token,String pw,String confirm)throws Exception{return call("POST","/auth/reset-password",null,Map.of("token",token,"newPassword",pw,"confirmPassword",confirm));}

    @BeforeEach void isolateRateLimits()throws Exception{var target=org.springframework.test.util.AopTestUtils.getTargetObject(verification);((Map<?,?>)org.springframework.test.util.ReflectionTestUtils.getField(target,"limits")).clear();}

    @Test void resetRevokesSessionsAndPreservesProfileAndVerification()throws Exception{var a=account();String one=login(a.email,OLD),two=login(a.email,OLD);String t=issue(a);var pending=accounts.findById(a.id).orElseThrow();assertTrue(passwords.matches(OLD,pending.passwordHash));assertEquals(a.authVersion,pending.authVersion);assertEquals(EmailVerification.hash(t),pending.passwordResetHash);assertNotEquals(t,pending.passwordResetHash);assertTrue(pending.passwordResetExpiresAt.isAfter(Instant.now().plusSeconds(1700)));var result=reset(t,NEW,NEW);assertEquals(200,result.statusCode(),result.body());assertFalse(tree(result).has("token"));assertEquals(401,call("GET","/auth/me",one,null).statusCode());assertEquals(401,call("GET","/auth/me",two,null).statusCode());assertEquals(403,call("GET","/student/profile",one,null).statusCode());assertEquals(401,call("POST","/auth/login",null,Map.of("email",a.email,"password",OLD)).statusCode());String current=login(a.email,NEW);assertEquals(200,call("GET","/student/profile",current,null).statusCode());var saved=accounts.findById(a.id).orElseThrow();assertTrue(saved.emailVerified);assertEquals(a.emailVerifiedAt,saved.emailVerifiedAt);assertEquals(a.role,saved.role);assertEquals(8.7,profiles.findByUserId(a.id).orElseThrow().cgpa);assertNull(saved.passwordResetHash);assertNull(saved.passwordResetExpiresAt);assertFalse(saved.passwordHash.equals(NEW));assertTrue(call("GET","/notifications",current,null).body().contains("Password changed"));assertEquals(400,reset(t,"Other@12345","Other@12345").statusCode());}
    @Test void expirationReplacementAndCooldown()throws Exception{var a=account();String old=issue(a);String body=request(a.email).body();assertEquals(body,request("unknown@example.com").body());synchronized(mail.messages){assertEquals(1,mail.messages.stream().filter(m->m.to().equals(a.email)&&m.kind()==VerificationMail.Kind.PASSWORD_RESET).count());}var saved=accounts.findById(a.id).orElseThrow();saved.passwordResetExpiresAt=Instant.now().minusSeconds(1);saved.passwordResetSentAt=Instant.now().minusSeconds(61);accounts.save(saved);assertEquals(400,reset(old,NEW,NEW).statusCode());assertEquals(202,request(a.email.toUpperCase(Locale.ROOT)).statusCode());String replacement=awaitToken(a,old);assertNotEquals(old,replacement);assertEquals(400,reset(old,NEW,NEW).statusCode());assertEquals(200,reset(replacement,NEW,NEW).statusCode());}
    @Test void invalidPasswordsDoNotConsumeTheLink()throws Exception{var a=account();String t=issue(a);assertEquals(400,reset(t,NEW,"Different@12345").statusCode());assertEquals(400,reset(t,"weakpassword","weakpassword").statusCode());assertEquals(400,reset(t,OLD,OLD).statusCode());String unicode="é".repeat(40)+"Ab1";assertEquals(400,reset(t,unicode,unicode).statusCode());assertEquals(EmailVerification.hash(t),accounts.findById(a.id).orElseThrow().passwordResetHash);assertEquals(400,reset("bad",NEW,NEW).statusCode());assertEquals(400,reset("A".repeat(43),NEW,NEW).statusCode());assertEquals(200,reset(t,NEW,NEW).statusCode());}
    @Test void tokenPurposesStaySeparateAndPendingAccountsStayPending()throws Exception{var a=account();a.emailVerified=false;a.emailVerifiedAt=null;String verificationToken="V".repeat(43);a.verificationHash=EmailVerification.hash(verificationToken);a.verificationExpiresAt=Instant.now().plusSeconds(86400);accounts.save(a);String resetToken=issue(a);assertEquals(400,reset(verificationToken,NEW,NEW).statusCode());assertEquals(400,call("POST","/auth/verify-email",null,Map.of("token",resetToken)).statusCode());assertEquals(200,reset(resetToken,NEW,NEW).statusCode());assertFalse(accounts.findById(a.id).orElseThrow().emailVerified);assertEquals(403,call("POST","/auth/login",null,Map.of("email",a.email,"password",NEW)).statusCode());assertEquals(200,call("POST","/auth/verify-email",null,Map.of("token",verificationToken)).statusCode());login(a.email,NEW);}
    @Test void passwordSettingsInvalidateOutstandingResetLinks()throws Exception{var a=account();String jwt=login(a.email,OLD),t=issue(a);assertEquals(200,call("PATCH","/account",jwt,Map.of("currentPassword",OLD,"newPassword",NEW)).statusCode());assertEquals(400,reset(t,"Third@12345","Third@12345").statusCode());login(a.email,NEW);}
    @Test void disabledAccountsCannotRecoverAndRepliesStayGeneric()throws Exception{var a=account();String t=issue(a);var saved=accounts.findById(a.id).orElseThrow();saved.enabled=false;accounts.save(saved);var disabled=request(a.email);var unknown=request("absent@example.com");assertEquals(disabled.statusCode(),unknown.statusCode());assertEquals(disabled.body(),unknown.body());assertEquals(400,reset(t,NEW,NEW).statusCode());assertEquals(401,call("POST","/auth/login",null,Map.of("email",a.email,"password",OLD)).statusCode());}
    @Test void concurrentConsumptionHasOneWinner()throws Exception{var a=account();String t=issue(a);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);Callable<Integer> task=()->{start.await();return reset(t,NEW,NEW).statusCode();};try{var one=pool.submit(task);var two=pool.submit(task);start.countDown();var codes=new ArrayList<>(List.of(one.get(),two.get()));Collections.sort(codes);assertEquals(List.of(200,400),codes);}finally{pool.shutdownNow();}}
    @Test void inboxHasDistinctMessagesAndResetNavigation()throws Exception{var a=account();String t=issue(a);mail.send(a.email,"http://localhost:5173/verify-email#token="+"V".repeat(43),24);String all=mail.renderInbox(a.email);assertTrue(all.contains("Verify your CareerBridge email"));assertTrue(all.contains("Reset your CareerBridge password"));String reset=mail.renderInbox(a.email,"reset");assertTrue(reset.contains("Expires after 30 minutes"));assertTrue(reset.contains("Back to password recovery"));assertTrue(reset.contains("/forgot-password?email="));assertFalse(reset.contains("Verify your CareerBridge email"));assertTrue(reset.contains("target=\"_self\""));assertTrue(reset.contains(t));for(int i=0;i<10;i++)verification.limit("reset-rate-test","forgot-password");assertEquals(429,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->verification.limit("reset-rate-test","forgot-password")).getStatusCode().value());}
}
